"""``rasa skills`` — short top-level alias for ``rasa tools skills``.

Subcommands:
- ``rasa skills install`` — alias of ``rasa tools skills install``
- ``rasa skills list`` — alias of ``rasa tools skills list``

Both subcommands reuse the exact argument definitions
(``rasa.cli.arguments.tools``) and handlers (``rasa.cli.tools.skills``) as
their ``rasa tools skills`` counterparts, so behavior is identical between
the two command surfaces. ``rasa tools skills install``/``list`` are
unaffected by this alias and keep working unchanged.
"""

import argparse
from typing import List

from rasa.cli import SubParsersAction


def add_subparser(
    subparsers: SubParsersAction, parents: List[argparse.ArgumentParser]
) -> None:
    """Add the top-level ``rasa skills`` parser.

    Args:
        subparsers: subparser we are going to attach to
        parents: Parent parsers, needed to ensure tree structure in argparse
    """
    from rasa.cli.arguments.tools import (
        set_tools_skills_install_arguments,
        set_tools_skills_list_arguments,
    )
    from rasa.cli.tools.skills import skills_install, skills_list

    skills_parser = subparsers.add_parser(
        "skills",
        conflict_handler="resolve",
        formatter_class=argparse.ArgumentDefaultsHelpFormatter,
        parents=parents,
        help="Manage Rasa agent skills for IDE copilots.",
    )
    skills_parser.set_defaults(func=lambda _: skills_parser.print_help(None))

    skills_subparsers = skills_parser.add_subparsers()

    skills_install_parser = skills_subparsers.add_parser(
        "install",
        conflict_handler="resolve",
        formatter_class=argparse.ArgumentDefaultsHelpFormatter,
        parents=parents,
        help="Download and install agent skills for a Rasa engine.",
    )
    skills_install_parser.set_defaults(func=skills_install)
    set_tools_skills_install_arguments(skills_install_parser)

    skills_list_parser = skills_subparsers.add_parser(
        "list",
        conflict_handler="resolve",
        formatter_class=argparse.ArgumentDefaultsHelpFormatter,
        parents=parents,
        help="List available agent skills per Rasa engine.",
    )
    skills_list_parser.set_defaults(func=skills_list)
    set_tools_skills_list_arguments(skills_list_parser)
